const newsKinds={feature:'Новая функция',improvement:'Улучшение',fix:'Исправление'};
const newsPriorities={important:['★','Важно'],normal:['●','Обычное'],minor:['🔧','Мелкое исправление']};
const newsState={search:'',from:'',to:'',type:'',priority:'',sort:'newest',page:0};
function newsFiltered(){const term=newsState.search.trim().toLocaleLowerCase('ru-RU');return SITE_CHANGELOG.filter(x=>(!term||[x.title,x.description,x.version,x.author,newsKinds[x.type]].join(' ').toLocaleLowerCase('ru-RU').includes(term))&&(!newsState.from||x.date>=newsState.from)&&(!newsState.to||x.date<=newsState.to)&&(!newsState.type||x.type===newsState.type)&&(!newsState.priority||x.priority===newsState.priority)).sort((a,b)=>{const av=Number(a.version.split('.')[0])*10+Number(a.version.split('.')[1]),bv=Number(b.version.split('.')[0])*10+Number(b.version.split('.')[1]);if(newsState.sort==='version')return av-bv;const order=a.date.localeCompare(b.date)||av-bv;return newsState.sort==='oldest'?order:-order})}
function newsDate(date){return date.split('-').reverse().join('.')}
function renderNewsResults(){const box=$('#newsResults');if(!box)return;const all=newsFiltered(),size=10,pages=Math.max(1,Math.ceil(all.length/size));newsState.page=Math.max(0,Math.min(newsState.page,pages-1));const list=all.slice(newsState.page*size,(newsState.page+1)*size);box.innerHTML=`<div class="news-result-top"><span role="status">Найдено: <b>${all.length}</b> из ${SITE_CHANGELOG.length}</span><label>К версии <select class="input" data-news-jump><option value="">Выберите</option>${all.map(x=>`<option value="${x.version}">${x.version} · ${esc(x.title)}</option>`).join('')}</select></label></div><div class="news-list">${list.map(x=>{const [icon,label]=newsPriorities[x.priority];return `<article class="news-entry" id="news-${x.version.replace('.','-')}"><div class="news-entry-meta"><b class="news-version">${x.version}</b><time datetime="${x.date}">${newsDate(x.date)}</time><span class="news-priority ${x.priority}"><span aria-hidden="true">${icon}</span> ${label}</span><span class="news-author">Автор: ${esc(x.author||'Имя не записано')}</span><span class="news-kind">${newsKinds[x.type]}</span></div><h2>${esc(x.title)}</h2><p>${esc(x.description)}</p></article>`}).join('')||'<div class="empty">Изменения не найдены. Попробуйте изменить фильтры.</div>'}</div><nav class="news-pages" aria-label="Страницы истории"><button class="btn btn-ghost small" data-news-page="-1" type="button" ${newsState.page===0?'disabled':''}>← Назад</button><span>${newsState.page+1} / ${pages}</span><button class="btn btn-ghost small" data-news-page="1" type="button" ${newsState.page>=pages-1?'disabled':''}>Далее →</button></nav>`}
ADM_TABS.push(['whatsnew','Что нового?']);
ADM_RENDER.whatsnew=function(){$('#admMain').innerHTML=`<header class="adm-head"><h1>Что нового?</h1><p class="sub">Доработки и функции сайта с версии 1.0. Даты — по московскому времени.</p></header><section class="panel news-controls"><label class="field">Поиск<input class="input" type="search" data-news-filter="search" value="${esc(newsState.search)}" placeholder="Название, изменение или версия"></label><div class="news-filter-grid"><label class="field">С даты<input class="input" type="date" data-news-filter="from" value="${newsState.from}"></label><label class="field">По дату<input class="input" type="date" data-news-filter="to" value="${newsState.to}"></label><label class="field">Тип<select class="input" data-news-filter="type"><option value="">Все изменения</option>${Object.entries(newsKinds).map(([k,v])=>`<option value="${k}" ${newsState.type===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Значимость<select class="input" data-news-filter="priority"><option value="">Все отметки</option>${Object.entries(newsPriorities).map(([k,[icon,v]])=>`<option value="${k}" ${newsState.priority===k?'selected':''}>${icon} ${v}</option>`).join('')}</select></label><label class="field">Порядок<select class="input" data-news-filter="sort"><option value="newest" ${newsState.sort==='newest'?'selected':''}>Сначала новые</option><option value="oldest" ${newsState.sort==='oldest'?'selected':''}>Сначала старые</option><option value="version" ${newsState.sort==='version'?'selected':''}>От версии 1.0</option></select></label><button class="btn btn-ghost small" type="button" data-news-reset>Сбросить</button></div></section><section id="newsResults" aria-label="История обновлений"></section>`;renderNewsResults()};
document.addEventListener('input',e=>{const key=e.target.dataset.newsFilter;if(!key||!(key in newsState))return;newsState[key]=e.target.value;newsState.page=0;renderNewsResults()});
document.addEventListener('change',e=>{if(!e.target.matches('[data-news-jump]')||!e.target.value)return;const version=e.target.value,all=newsFiltered(),index=all.findIndex(x=>x.version===version);if(index<0)return;newsState.page=Math.floor(index/10);renderNewsResults();document.getElementById('news-'+version.replace('.','-'))?.scrollIntoView({block:'center',behavior:'smooth'})});
document.addEventListener('click',e=>{const page=e.target.closest('[data-news-page]');if(page){newsState.page+=Number(page.dataset.newsPage);renderNewsResults();$('#newsResults')?.scrollIntoView({block:'start'});}if(e.target.closest('[data-news-reset]')){Object.assign(newsState,{search:'',from:'',to:'',type:'',priority:'',sort:'newest',page:0});ADM_RENDER.whatsnew()}});

SITE_CHANGELOG.push({version:'5.9',author:'Руслан',date:'2026-10-12',title:'Автоматический журнал обновления контента',type:'feature',priority:'normal',description:'Отдельный раздел админки записывает новые экскурсии и изменения текстов, фотографий, цен и расписания при сохранении. Поиск, даты и постраничная навигация.'});
let contentHistory=[];const contentHistoryState={search:'',from:'',to:'',sort:'newest',page:0};
function contentHistoryFiltered(){const term=contentHistoryState.search.trim().toLocaleLowerCase('ru-RU');return contentHistory.filter(x=>{const date=new Date(x.at).toLocaleDateString('sv-SE',{timeZone:'Europe/Moscow'});return (!term||[x.author||'',...x.changes].join(' ').toLocaleLowerCase('ru-RU').includes(term))&&(!contentHistoryState.from||date>=contentHistoryState.from)&&(!contentHistoryState.to||date<=contentHistoryState.to)}).sort((a,b)=>contentHistoryState.sort==='oldest'?a.at-b.at:b.at-a.at)}
function renderContentHistoryResults(){const box=$('#contentHistoryResults');if(!box)return;const all=contentHistoryFiltered(),pages=Math.max(1,Math.ceil(all.length/10));contentHistoryState.page=Math.max(0,Math.min(contentHistoryState.page,pages-1));box.innerHTML=`<p class="sub" role="status">Найдено записей: ${all.length}</p><div class="news-list">${all.slice(contentHistoryState.page*10,(contentHistoryState.page+1)*10).map(x=>`<article class="news-entry"><div class="news-entry-meta"><b class="news-version">Контент · ${x.id}</b><time datetime="${new Date(x.at).toISOString()}">${new Date(x.at).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',dateStyle:'short',timeStyle:'short'})} МСК</time><span class="news-author">Автор: ${esc(x.author||'Имя не записано')}</span></div><ul class="content-change-list">${x.changes.map(text=>`<li>${esc(text)}</li>`).join('')}</ul></article>`).join('')||'<div class="empty">Записей пока нет. Новые изменения контента появятся здесь после сохранения в админке.</div>'}</div><nav class="news-pages" aria-label="Страницы изменений контента"><button type="button" class="btn btn-ghost small" data-content-page="-1" ${contentHistoryState.page===0?'disabled':''}>← Назад</button><span>${contentHistoryState.page+1} / ${pages}</span><button type="button" class="btn btn-ghost small" data-content-page="1" ${contentHistoryState.page>=pages-1?'disabled':''}>Далее →</button></nav>`}
async function loadContentHistory(){const box=$('#contentHistoryResults');if(!box)return;box.innerHTML='<p class="sub" role="status">Загрузка истории…</p>';try{const data=await api('/api/admin/content-history');if($('#contentHistoryResults')!==box)return;contentHistory=data.entries||[];renderContentHistoryResults()}catch(err){if($('#contentHistoryResults')===box)box.innerHTML=`<p class="err" role="alert">${esc(err.message)}</p><button type="button" class="btn btn-ghost small" data-content-refresh>Повторить</button>`}}
ADM_TABS.push(['contenthistory','Обновление контента']);
ADM_RENDER.contenthistory=function(){$('#admMain').innerHTML=`<header class="adm-head"><h1>Обновление контента</h1><p class="sub">Новые экскурсии и изменения текстов, фотографий, тарифов и настроек записываются автоматически при сохранении. Журнал ведётся с 12 октября 2026 года.</p></header><section class="panel news-controls"><label class="field">Поиск<input type="search" class="input" data-content-filter="search" value="${esc(contentHistoryState.search)}" placeholder="Экскурсия, текст, фотография…"></label><div class="news-filter-grid"><label class="field">С даты<input type="date" class="input" data-content-filter="from" value="${contentHistoryState.from}"></label><label class="field">По дату<input type="date" class="input" data-content-filter="to" value="${contentHistoryState.to}"></label><label class="field">Порядок<select class="input" data-content-filter="sort"><option value="newest" ${contentHistoryState.sort==='newest'?'selected':''}>Сначала новые</option><option value="oldest" ${contentHistoryState.sort==='oldest'?'selected':''}>Сначала старые</option></select></label><button type="button" class="btn btn-ghost small" data-content-refresh>Обновить журнал</button></div></section><section id="contentHistoryResults"></section>`;loadContentHistory()};
document.addEventListener('input',e=>{const key=e.target.dataset.contentFilter;if(!key||!(key in contentHistoryState))return;contentHistoryState[key]=e.target.value;contentHistoryState.page=0;renderContentHistoryResults()});
document.addEventListener('click',e=>{if(e.target.closest('[data-content-refresh]'))loadContentHistory();const button=e.target.closest('[data-content-page]');if(button){contentHistoryState.page+=Number(button.dataset.contentPage);renderContentHistoryResults();$('#contentHistoryResults')?.scrollIntoView({block:'start'})}});


const adminGroups=[['Работа',['dash','requests','push']],['Контент',['tours','stops','transfer','services','stories','reviews','moderation']],['Оформление',['hero','popular','texts','typography','site']],['Система',['whatsnew','contenthistory','backup','settings']]];
/* ---------- Admin navigation, build 152: every section visible, grouped by task, with counters ----------
   The old adminGroups list stays for modules that append sections to it; the menu is laid out by key. */
const ADMIN_NAV_LAYOUT=[['Работа',['dash','requests','moderation','push']],['Каталог',['tours','popular','stops','transfer','fleet','services']],['Сайт',['hero','texts','stories','reviews','typography','site','visual']],['Система',['whatsnew','contenthistory','backup','settings']]];
const ADMIN_CATALOG_KEYS=['tours','popular','stops','transfer','fleet','services'];
const ADMIN_STATUS_LABEL={pending:'новая',needs_info:'ждём ответа гостя',confirmed:'подтверждена',awaiting_payment:'ждёт оплаты',paid:'в работе',completed:'выполнена',rejected:'отклонена',cancelled:'отменена'};
const admSvg=paths=>`<svg class="adm-nav-icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths}</svg>`;
