function adminNavIcon(key){return admSvg(ADMIN_NAV_ICONS[key]||'<circle cx="12" cy="12" r="8"/>')}
function adminCurrentTabs(){if(serverStaffRole==='dispatcher'||serverStaffRole==='observer')return ADM_TABS.filter(t=>t[0]==='requests');if(serverEditor)return ADM_TABS.filter(t=>['tours','stops','services','popular','whatsnew','contenthistory'].includes(t[0]));return ADM_TABS.filter(t=>t[0]!=='staff'||serverStaffRole==='owner')}
function adminNavGroups(tabs){const used=new Set(),groups=ADMIN_NAV_LAYOUT.map(([label,keys])=>[label,keys.map(key=>tabs.find(t=>t[0]===key)).filter(Boolean)]);for(const [,items] of groups)for(const [key] of items)used.add(key);const rest=tabs.filter(([key])=>!used.has(key));if(rest.length)groups.push(['Другое',rest]);return groups.filter(([,items])=>items.length)}
function adminOrderStatus(order){return order.status==='private'?'pending':order.status||'pending'}
function adminAllOrders(){return [...(store.get('bookings',[])||[]).map(o=>({...o,kind:'bookings'})),...(store.get('transfers',[])||[]).map(o=>({...o,kind:'transfers'}))]}
function adminOrderTitle(order){return order.kind==='bookings'?tourById(order.tour)?.title||order.tour||'Экскурсия':order.route||'Трансфер'}
function adminOrderPeople(order){return order.kind==='transfers'?Number(order.pax)||0:(Number(order.adults)||0)+(Number(order.kids)||0)}
function adminNavBadge(key){if(key==='requests')return adminAllOrders().filter(o=>adminOrderStatus(o)==='pending').length;if(key==='moderation')return (store.get('diary',[])||[]).filter(s=>s.status==='pending').length;return 0}
function adminShortcutLabel(){return /Mac|iPhone|iPad/.test(navigator.platform||navigator.userAgent||'')?'⌘K':'Ctrl K'}
function adminNavigation(tabs,active){return `<button type="button" class="adm-search-open" data-admin-palette aria-haspopup="dialog" aria-keyshortcuts="Meta+K Control+K">${adminNavIcon('search')}<span>Поиск по админке</span><kbd>${adminShortcutLabel()}</kbd></button><nav class="adm-nav" aria-label="Разделы админки">${adminNavGroups(tabs).map(([label,items])=>`<div class="adm-nav-section"><p class="adm-nav-heading">${esc(label)}</p>${items.map(([key,name])=>{const badge=adminNavBadge(key),count=key==='tours'?C.tours.length:0;return `<a href="#/admin/${key}" data-admin-nav="${key}" ${active===key?'aria-current="page"':''}>${adminNavIcon(key)}<span class="adm-nav-name">${esc(name)}</span>${badge?`<b class="adm-nav-badge${key==='requests'?' is-accent':''}">${badge}<span class="sr-only"> ${key==='requests'?'новых':'на проверке'}</span></b>`:count?`<small class="adm-nav-count">${count}</small>`:''}</a>`}).join('')}</div>`).join('')}</nav>`}

/* Phone: the admin keeps its own bottom bar; «Ещё» opens every section as a sheet (the same menu). */
function renderAdminTabbar(tabs,active){document.documentElement.classList.remove('adm-more-lock');let bar=$('#admTabbar');if(!bar){bar=document.createElement('nav');bar.id='admTabbar';bar.className='adm-tabbar';bar.setAttribute('aria-label','Админка');document.body.appendChild(bar)}const has=key=>tabs.some(t=>t[0]===key),inCatalog=ADMIN_CATALOG_KEYS.includes(active),items=[['dash','Сегодня'],['requests','Заявки'],['tours','Каталог']].filter(([key])=>has(key)),covered=items.some(([key])=>key===active||key==='tours'&&inCatalog);bar.style.setProperty('--adm-tabs',String(items.length+1));bar.innerHTML=items.map(([key,label])=>{const on=key===active||key==='tours'&&inCatalog,badge=key==='requests'?adminNavBadge('requests'):0;return `<a href="#/admin/${key}" ${on?'aria-current="page"':''}>${adminNavIcon(key)}<span>${label}</span>${badge?`<b class="adm-tab-badge">${badge}<span class="sr-only"> новых</span></b>`:''}</a>`}).join('')+`<button type="button" data-admin-more aria-controls="admSide" aria-expanded="false"${covered?'':' class="is-current"'}>${adminNavIcon('more')}<span>Ещё</span></button>`}
function setAdminMore(open){const root=$('#app .adm'),side=$('#admSide'),scrim=$('#app .adm-scrim');if(!root||!side)return;root.classList.toggle('is-more-open',open);if(scrim)scrim.hidden=!open;$('#admTabbar [data-admin-more]')?.setAttribute('aria-expanded',String(open));document.documentElement.classList.toggle('adm-more-lock',open);if(open){side.setAttribute('role','dialog');side.setAttribute('aria-modal','true');side.setAttribute('aria-labelledby','admSheetTitle');setTimeout(()=>$('.adm-search-open',side)?.focus({preventScroll:true}),40)}else{side.removeAttribute('role');side.removeAttribute('aria-modal');side.removeAttribute('aria-labelledby')}}
document.addEventListener('click',e=>{if(e.target.closest('[data-admin-more]')){setAdminMore(!$('#app .adm')?.classList.contains('is-more-open'));return}if(e.target.closest('[data-admin-more-close]')){setAdminMore(false);$('#admTabbar [data-admin-more]')?.focus({preventScroll:true});return}if(e.target.closest('#admSide a[href]'))setAdminMore(false)});
matchMedia('(max-width: 900px)').addEventListener?.('change',e=>{if(!e.matches)setAdminMore(false)});

/* Quick jump (⌘K / Ctrl K): sections, tours, requests and actions. It navigates by address, so the
   unsaved-changes prompt still guards every jump. */
const adminPalette={el:null,items:[],index:0,opener:null};
/* Same path as a clicked link: unsaved edits first ask «Сохранить изменения?».
   `after` belongs to this one jump: it runs only if the jump really happens («Да, сохранить» or «Нет, выйти»),
   never after «Отмена», and never once a newer jump has started. Nothing is changed before the answer. */
let adminGoSeq=0;
function adminGo(hash,after){if(adminExitBusy)return;const seq=++adminGoSeq,go=()=>{if(seq!==adminGoSeq)return;if(hash!==location.hash){adminLastHash=hash;location.hash=hash}after?.(seq)};if(hash!==location.hash&&(adminDirty||adminSaving)){exitAdminDraft(go);return}go()}
/* Runs `fn` on the target page once it has rendered. It gives up for good if the jump is cancelled or
   replaced, if the address changes on the way, or after a few seconds. */
function adminWhenOn(hash,fn){adminGo(hash,seq=>{const until=Date.now()+4000;const tick=()=>{if(seq!==adminGoSeq||location.hash!==hash)return;const main=$('#admMain');if(main?.dataset.adminHash===hash&&$('[data-adm]',main)){fn();return}if(Date.now()<until)requestAnimationFrame(tick)};tick()})}
function adminOpenOrder(order){adminGo('#/admin/requests',()=>{Object.assign(requestQueueState,{status:'all',kind:'all',query:String(order.code||''),city:'all',from:'',to:'',sort:'attention'});if(!$('#admMain #requestQueueSearch'))return;$('#requestQueueSearch').value=requestQueueState.query;for(const [id,key] of [['requestQueueStatus','status'],['requestQueueKind','kind'],['requestQueueCity','city'],['requestQueueFrom','from'],['requestQueueTo','to'],['requestQueueSort','sort']]){const el=$('#'+id);if(el)el.value=requestQueueState[key]}applyRequestQueue()})}
function adminPaletteResults(term){const tabs=adminCurrentTabs(),has=key=>tabs.some(t=>t[0]===key),t=term.trim().toLocaleLowerCase('ru-RU'),match=v=>String(v??'').toLocaleLowerCase('ru-RU').includes(t),out=[];
 for(const [group,items] of adminNavGroups(tabs))for(const [key,name] of items)if(!t||match(name)||match(group))out.push({kind:'Разделы',label:name,hint:group,icon:key,hash:'#/admin/'+key});
 if(t&&has('tours'))C.tours.filter(tour=>match(tour.title)||match(tour.loc)).slice(0,6).forEach(tour=>out.push({kind:'Экскурсии',label:tour.title,hint:[tour.price!=null?'от '+rub(tour.price):'',tour.hidden?'скрыта':''].filter(Boolean).join(' · '),icon:'tours',hash:'#/admin/tours/'+encodeURIComponent(tour.id)}));
 if(t&&has('requests'))adminAllOrders().filter(o=>[o.code,o.name,o.phone,adminOrderTitle(o)].some(match)).sort((a,b)=>compareAdminOrders(a,b,'attention')).slice(0,6).forEach(o=>out.push({kind:'Заявки',label:adminOrderTitle(o)+(o.name?' · '+o.name:''),hint:[o.date?shortDate(o.date):'',o.code?'№ '+o.code:'',ADMIN_STATUS_LABEL[adminOrderStatus(o)]||''].filter(Boolean).join(' · '),icon:'requests',order:o}));
 const actions=[has('tours')&&{label:'Новая экскурсия',hint:'Каталог',icon:'tours',run:()=>adminWhenOn('#/admin/tours',()=>$('#admMain [data-adm="newtour"]')?.click())},has('push')&&{label:'Отправить push-уведомление',hint:'Работа',icon:'push',hash:'#/admin/push'},has('backup')&&{label:'Скачать резервную копию',hint:'Система',icon:'backup',hash:'#/admin/backup'},{label:'Открыть сайт',hint:'Главная страница',icon:'hero',hash:'#/'}].filter(Boolean);
 actions.filter(a=>!t||match(a.label)).forEach(a=>out.push({kind:'Действия',...a}));
 return out}
function openAdminPalette(){if(current!=='admin'||!isAdmin()||adminExitBusy||$('dialog[open]'))return;setAdminMore(false);if(adminPalette.el){$('input',adminPalette.el)?.focus();return}adminPalette.opener=document.activeElement;adminPalette.index=0;const el=document.createElement('div');el.className='adm-palette-layer';el.innerHTML=`<div class="adm-palette-scrim" data-palette-close></div><div class="adm-palette" role="dialog" aria-modal="true" aria-label="Быстрый переход"><label class="adm-palette-field">${adminNavIcon('search')}<input type="search" role="combobox" aria-expanded="true" aria-controls="admPaletteList" aria-autocomplete="list" aria-label="Раздел, экскурсия, заявка или действие" placeholder="Раздел, экскурсия, заявка или действие" autocomplete="off" spellcheck="false"><kbd>Esc</kbd></label><div class="adm-palette-list" id="admPaletteList" role="listbox" aria-label="Результаты"></div><div class="adm-palette-foot" aria-hidden="true"><span>↑↓ выбрать</span><span>↵ открыть</span><span>Esc закрыть</span></div></div>`;document.body.appendChild(el);adminPalette.el=el;document.documentElement.classList.add('adm-palette-lock');const input=$('input',el);input.addEventListener('input',()=>{adminPalette.index=0;drawAdminPalette()});input.addEventListener('keydown',adminPaletteKey);drawAdminPalette();requestAnimationFrame(()=>input.focus({preventScroll:true}))}
function drawAdminPalette(){const el=adminPalette.el;if(!el)return;const input=$('input',el),list=$('.adm-palette-list',el),term=input.value;adminPalette.items=adminPaletteResults(term);if(!adminPalette.items.length){list.innerHTML=`<p class="adm-palette-empty">Ничего не нашлось по запросу «${esc(term)}»</p>`;input.removeAttribute('aria-activedescendant');return}adminPalette.index=Math.min(adminPalette.index,adminPalette.items.length-1);let group='';list.innerHTML=adminPalette.items.map((item,i)=>{const head=item.kind!==group?`<p class="adm-palette-group" role="presentation">${esc(item.kind)}</p>`:'';group=item.kind;return head+`<div class="adm-palette-item" role="option" id="admPaletteOpt${i}" data-palette-index="${i}" aria-selected="${i===adminPalette.index}">${adminNavIcon(item.icon)}<span class="adm-palette-label">${esc(item.label)}</span>${item.hint?`<small>${esc(item.hint)}</small>`:''}</div>`}).join('');input.setAttribute('aria-activedescendant','admPaletteOpt'+adminPalette.index)}
function setAdminPaletteIndex(i){const el=adminPalette.el;if(!el)return;adminPalette.index=i;$$('[data-palette-index]',el).forEach(opt=>opt.setAttribute('aria-selected',String(Number(opt.dataset.paletteIndex)===i)));$('#admPaletteOpt'+i)?.scrollIntoView({block:'nearest'});$('input',el)?.setAttribute('aria-activedescendant','admPaletteOpt'+i)}
function adminPaletteKey(e){const n=adminPalette.items.length;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(n)setAdminPaletteIndex((adminPalette.index+(e.key==='ArrowDown'?1:-1)+n)%n)}else if(e.key==='Enter'){e.preventDefault();runAdminPaletteItem(adminPalette.items[adminPalette.index])}else if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closeAdminPalette()}else if(e.key==='Tab')e.preventDefault()}
function closeAdminPalette(restore=true){const el=adminPalette.el;if(!el)return;adminPalette.el=null;document.documentElement.classList.remove('adm-palette-lock');const opener=adminPalette.opener;adminPalette.opener=null;if(reduce)el.remove();else{el.classList.add('is-closing');setTimeout(()=>el.remove(),170)}if(restore&&opener?.isConnected)opener.focus({preventScroll:true})}
function runAdminPaletteItem(item){if(!item)return;closeAdminPalette(false);if(item.run)return item.run();if(item.order)return adminOpenOrder(item.order);if(item.hash)adminGo(item.hash)}
document.addEventListener('click',e=>{if(e.target.closest('[data-admin-palette]')){e.preventDefault();openAdminPalette();return}if(!adminPalette.el)return;if(e.target.closest('[data-palette-close]')){closeAdminPalette();return}const opt=e.target.closest('[data-palette-index]');if(opt&&adminPalette.el.contains(opt))runAdminPaletteItem(adminPalette.items[Number(opt.dataset.paletteIndex)])});
document.addEventListener('pointermove',e=>{const opt=e.target.closest?.('[data-palette-index]');if(!opt||!adminPalette.el?.contains(opt))return;const i=Number(opt.dataset.paletteIndex);if(i!==adminPalette.index)setAdminPaletteIndex(i)},{passive:true});
addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&!e.altKey&&!e.shiftKey&&(e.code==='KeyK'||String(e.key).toLowerCase()==='k')&&current==='admin'&&isAdmin()){e.preventDefault();if(adminPalette.el)closeAdminPalette();else openAdminPalette();return}if(e.key==='Escape'&&$('#app .adm.is-more-open')){setAdminMore(false);$('#admTabbar [data-admin-more]')?.focus({preventScroll:true})}});
addEventListener('hashchange',()=>{if(adminPalette.el)closeAdminPalette(false)});

/* «Сегодня»: built only from lists the admin already has; nothing new is asked of the server. */
function adminTodayData(){const orders=adminAllOrders(),tomorrow=tomorrowISO(),status=adminOrderStatus,attention=orders.filter(o=>status(o)==='pending').sort((a,b)=>compareAdminOrders(a,b,'attention')),waiting=orders.filter(o=>status(o)==='awaiting_payment').sort((a,b)=>compareAdminOrders(a,b,'dateAsc')),trips=orders.filter(o=>o.date===tomorrow&&['confirmed','awaiting_payment','paid'].includes(status(o))).sort((a,b)=>compareAdminOrders(a,b,'dateAsc'));let dateLabel='';try{dateLabel=new Intl.DateTimeFormat('ru-RU',{weekday:'long',day:'numeric',month:'long',timeZone:'Europe/Moscow'}).format(new Date()).replace(/^./,c=>c.toUpperCase())}catch{}return {attention,waiting,trips,tomorrow,questions:store.get('questions',[])||[],pendingStories:(store.get('diary',[])||[]).filter(s=>s.status==='pending').length,tomorrowPeople:trips.reduce((n,o)=>n+adminOrderPeople(o),0),dateLabel}}
function adminTodayOrderRow(order,lead){const amount=adminOrderAmount(order),people=adminOrderPeople(order),answered=order.clarification?.answeredAt&&!order.clarification?.reviewedAt,meta=[order.date?shortDate(order.date)+(order.time?', '+order.time:''):'',people?people+' чел.':'',amount!=null?rub(amount):'',order.kind==='bookings'?(order.city?'из '+order.city:''):(order.cls||''),order.name||''].filter(Boolean).join(' · ');return `<a class="adm-today-row" href="#/admin/requests" data-open-order="${esc(order.code||'')}"><span class="adm-today-dot is-${esc(adminOrderStatus(order))}" aria-hidden="true"></span><span class="adm-today-text"><b>${esc(answered?'Гость ответил на уточнение':lead)} · ${esc(adminOrderTitle(order))}</b><small>${esc(meta)}</small></span><span class="adm-today-go">Открыть</span></a>`}
function adminTodayAttentionHTML(today){const rows=[...today.attention.slice(0,6).map(o=>adminTodayOrderRow(o,o.kind==='transfers'?'Новая заявка на трансфер':'Новая заявка')),...today.waiting.slice(0,3).map(o=>adminTodayOrderRow(o,'Ждёт оплаты'))],more=today.attention.length-6;if(more>0)rows.push(`<a class="adm-today-more" href="#/admin/requests" data-today-queue="pending">Ещё ${more} ${plural(more,'новая заявка','новые заявки','новых заявок')}</a>`);if(today.questions.length)rows.push(`<a class="adm-today-row" href="#/admin/requests"><span class="adm-today-dot is-question" aria-hidden="true"></span><span class="adm-today-text"><b>Вопросы организатору · ${today.questions.length}</b><small>Открываются внизу раздела «Заявки»</small></span><span class="adm-today-go">Открыть</span></a>`);if(today.pendingStories)rows.push(`<a class="adm-today-row" href="#/admin/moderation"><span class="adm-today-dot is-story" aria-hidden="true"></span><span class="adm-today-text"><b>${today.pendingStories} ${plural(today.pendingStories,'история ждёт','истории ждут','историй ждут')} проверки</b><small>Модерация историй</small></span><span class="adm-today-go">Проверить</span></a>`);return rows.length?`<div class="adm-today-list">${rows.join('')}</div>`:'<p class="sub adm-today-empty">Новых заявок, вопросов и историй нет — всё обработано.</p>'}
function adminTodayTripsHTML(today){if(!today.trips.length)return `<p class="sub adm-today-empty">На ${esc(shortDate(today.tomorrow))} подтверждённых поездок нет.</p>`;const groups=new Map();for(const o of today.trips){const key=[o.kind,o.kind==='bookings'?o.tour:o.route,o.time||''].join('|');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(o)}return `<div class="adm-today-list">${[...groups.values()].map(list=>{const o=list[0],tour=o.kind==='bookings'?tourById(o.tour):null,people=list.reduce((n,x)=>n+adminOrderPeople(x),0);return `<a class="adm-today-row adm-today-trip" href="#/admin/requests" data-today-queue="tomorrow">${tour?`<img src="${esc(tourCover(tour,120,84))}" alt="" loading="lazy">`:`<span class="adm-today-icon">${adminNavIcon('transfer')}</span>`}<span class="adm-today-text"><b>${esc(adminOrderTitle(o))}</b><small>${esc([o.time||'',people?people+' чел.':'',list.length+' '+plural(list.length,'заявка','заявки','заявок')].filter(Boolean).join(' · '))}</small></span></a>`}).join('')}</div><p class="hint adm-today-note">Напоминания гостям уходят автоматически накануне поездки.</p>`}
document.addEventListener('click',e=>{const row=e.target.closest('[data-open-order]');if(row){Object.assign(requestQueueState,{status:'all',kind:'all',query:row.dataset.openOrder,city:'all',from:'',to:'',sort:'attention'});return}const queue=e.target.closest('[data-today-queue]');if(queue){const value=queue.dataset.todayQueue,day=tomorrowISO();Object.assign(requestQueueState,{status:value==='tomorrow'?'active':value,kind:'all',query:'',city:'all',from:value==='tomorrow'?day:'',to:value==='tomorrow'?day:'',sort:value==='tomorrow'?'dateAsc':'attention'})}},true);
const adminFoldState=new Map();
function setAdminFold(section,open){const body=$('.adm-body',section),button=$('[data-admin-fold]',section);if(!body||!button)return;body.hidden=!open;button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',(open?'Свернуть: ':'Развернуть: ')+section.dataset.sectionTitle);button.innerHTML=`<span>${open?'Свернуть':'Развернуть'}</span><svg viewBox="0 0 24 24" width="16" height="16" fill="none" aria-hidden="true"><path d="m6 9 6 6 6-6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;section.classList.toggle('adm-folded',!open);adminFoldState.set(section.dataset.foldKey,open)}
function normalizeAdminCards(root){for(const section of $$('.adm-card',root)){let head=$(':scope > header',section),body=$(':scope > .adm-body',section);if(head&&body)continue;if(!head){head=document.createElement('header');const oldTitle=$(':scope > h2,:scope > h3',section),title=document.createElement('h3');if(oldTitle){while(oldTitle.firstChild)title.appendChild(oldTitle.firstChild);oldTitle.remove()}else title.textContent=section.dataset.sectionTitle||'Настройки';head.appendChild(title);section.prepend(head)}if(!body){body=document.createElement('div');body.className='adm-body';for(const node of [...section.childNodes])if(node!==head)body.appendChild(node);section.appendChild(body)}}}
function setupCompactAdmin(){const root=$('#admMain');if(!root)return;normalizeAdminCards(root);expireAdminNav();const cards=$$('.adm-card',root),route=location.hash;cards.forEach((section,index)=>{const head=$(':scope > header',section),body=$(':scope > .adm-body',section),title=head?.querySelector('h3')?.textContent;if(!head||!body||!title||head.querySelector('[data-admin-fold]'))return;section.dataset.sectionTitle=title;section.dataset.foldKey=route+'|'+title+'|'+index;section.id='admin-section-'+index;head.insertAdjacentHTML('beforeend',`<button type="button" class="adm-drag-handle" data-admin-drag aria-label="Переместить блок: ${esc(title)}" title="Перетащите блок · клавиши ↑ и ↓"><svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="8" cy="5" r="2"/><circle cx="16" cy="5" r="2"/><circle cx="8" cy="12" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="8" cy="19" r="2"/><circle cx="16" cy="19" r="2"/></svg></button><button type="button" class="adm-fold-toggle" data-admin-fold aria-controls="admin-body-${index}" aria-expanded="true" aria-label="Свернуть: ${esc(title)}"><span aria-hidden="true">⌄</span></button>`);body.id='admin-body-'+index;const open=adminFoldState.has(section.dataset.foldKey)?adminFoldState.get(section.dataset.foldKey):index<2||/Сезоны|Основн|Отправка|Баннер|Контакты/.test(title);setAdminFold(section,open)});
 restoreAdminOrder(cards);
 if(cards.length>1&&!$('.adm-section-tools',root)){const head=$('.adm-head',root);head?.insertAdjacentHTML('afterend',`<div class="adm-section-tools"><label>К блоку<select class="input" data-admin-jump><option value="">Выберите…</option>${cards.map((card,i)=>`<option value="${i}">${esc(card.dataset.sectionTitle||'Блок '+(i+1))}</option>`).join('')}</select></label><div><button type="button" class="btn btn-ghost small" data-admin-fold-all="open">Развернуть всё</button><button type="button" class="btn btn-ghost small" data-admin-fold-all="close">Свернуть всё</button></div></div>`)}
 const jump=$('[data-admin-jump]',root);if(jump)jump.innerHTML='<option value="">Выберите…</option>'+$$('.adm-card',root).map(section=>`<option value="${section.id.replace('admin-section-','')}">${esc(section.dataset.sectionTitle||'Блок')}</option>`).join('');

}
