function adminOrderKey(){return 'apsua-admin-block-order:'+String(serverIdentity?.id||'admin')+':'+location.hash}
function persistAdminOrder(){try{localStorage.setItem(adminOrderKey(),JSON.stringify($$('#admMain .adm-card').map(section=>section.dataset.foldKey)))}catch{}}
function restoreAdminOrder(cards){let saved;try{saved=JSON.parse(localStorage.getItem(adminOrderKey())||'[]')}catch{return}if(!Array.isArray(saved)||!saved.length)return;const rank=new Map(saved.map((key,index)=>[key,index])),parents=new Map();cards.forEach(card=>{if(!parents.has(card.parentNode))parents.set(card.parentNode,[]);parents.get(card.parentNode).push(card)});for(const group of parents.values()){const ordered=group.slice().sort((a,b)=>(rank.get(a.dataset.foldKey)??99999)-(rank.get(b.dataset.foldKey)??99999));const slots=group.map(card=>{const marker=document.createComment('admin-block');card.before(marker);return marker});slots.forEach((slot,i)=>slot.replaceWith(ordered[i]))}}
let adminDrag=null;
document.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-admin-drag]');if(!handle||e.button!==0)return;const section=handle.closest('.adm-card');adminDrag={section,handle,id:e.pointerId,start:e.clientY,moved:false,key:adminOrderKey()};handle.setPointerCapture?.(e.pointerId)});
document.addEventListener('pointermove',e=>{const drag=adminDrag;if(!drag||e.pointerId!==drag.id)return;if(!drag.moved&&Math.abs(e.clientY-drag.start)<6)return;drag.moved=true;drag.section.classList.add('adm-is-dragging');e.preventDefault();if(e.clientY<70)window.scrollBy(0,-18);else if(e.clientY>innerHeight-70)window.scrollBy(0,18);const cards=$$('.adm-card',drag.section.parentNode).filter(card=>card.parentNode===drag.section.parentNode&&card!==drag.section);for(const target of cards){const r=target.getBoundingClientRect();if(e.clientY<r.top||e.clientY>r.bottom)continue;if(e.clientY<r.top+r.height/2)target.before(drag.section);else target.after(drag.section);break}},{passive:false});
function finishAdminDrag(e){const drag=adminDrag;if(!drag||e.pointerId!==drag.id)return;adminDrag=null;drag.section.classList.remove('adm-is-dragging');if(drag.moved){drag.handle._dragAt=Date.now();if(drag.key===adminOrderKey())persistAdminOrder();drag.handle.focus({preventScroll:true})}}
document.addEventListener('pointerup',finishAdminDrag);document.addEventListener('pointercancel',finishAdminDrag);
document.addEventListener('keydown',e=>{const handle=e.target.closest('[data-admin-drag]');if(!handle||!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const section=handle.closest('.adm-card'),cards=$$('.adm-card',section.parentNode).filter(card=>card.parentNode===section.parentNode),index=cards.indexOf(section),target=cards[index+(e.key==='ArrowUp'?-1:1)];if(!target)return;if(e.key==='ArrowUp')target.before(section);else target.after(section);persistAdminOrder();handle.focus({preventScroll:true})});
document.addEventListener('click',e=>{const handle=e.target.closest('[data-admin-drag]');if(handle){e.preventDefault();return}const head=e.target.closest('.adm-card > header');if(!head||e.target.closest('button,a,input,select,textarea,label,[role="button"]'))return;const section=head.closest('.adm-card'),fold=$('[data-admin-fold]',section);if(fold)setAdminFold(section,fold.getAttribute('aria-expanded')!=='true')});
SITE_CHANGELOG.push({version:'6.2',date:'2026-10-12',author:'Руслан',title:'Раскрытие по плашке и перестановка блоков',type:'improvement',priority:'normal',description:'Нажатие на заголовок раскрывает блок. Перетаскивание за значок мышью или пальцем меняет порядок; он сохраняется для вкладки в текущем браузере. Доступна перестановка клавишами вверх и вниз.'});

let adminNavTimer=0;
function adminNavStateKey(){return 'apsua-admin-nav-mode:'+String(serverIdentity?.id||'admin')}
function readAdminNavState(){try{return JSON.parse(localStorage.getItem(adminNavStateKey())||'{}')}catch{return {}}}
function adminNavLastActivity(){try{return Number(localStorage.getItem(adminNavStateKey()+':activity'))||0}catch{return 0}}
function adminNavIsOpen(label){const value=readAdminNavState()[label];return !!(value?.open&&Date.now()-Math.max(value.at,adminNavLastActivity())<300000)}
function expireAdminNav(){clearTimeout(adminNavTimer);const state=readAdminNavState(),now=Date.now(),last=Math.max(adminNavLastActivity(),...Object.values(state).map(value=>Number(value.at)||0));if(!Object.keys(state).length)return;const remaining=300000-(now-last);if(remaining<=0){try{localStorage.removeItem(adminNavStateKey());localStorage.removeItem(adminNavStateKey()+':activity')}catch{}$$('.adm-nav-group').forEach(group=>group.open=false)}else adminNavTimer=setTimeout(expireAdminNav,remaining+20)}
function saveAdminNavMode(group){const state=readAdminNavState();state[group.dataset.navGroup]={open:group.open,at:Date.now()};try{localStorage.setItem(adminNavStateKey(),JSON.stringify(state));localStorage.setItem(adminNavStateKey()+':activity',String(Date.now()))}catch{}expireAdminNav()}
let adminActivityAt=0;
function noteAdminActivity(){if(!document.body.classList.contains('is-admin'))return;const now=Date.now();if(now-adminActivityAt<5000)return;expireAdminNav();adminActivityAt=now;try{localStorage.setItem(adminNavStateKey()+':activity',String(now))}catch{}expireAdminNav()}
for(const event of ['pointerdown','pointermove','keydown','input','wheel'])document.addEventListener(event,noteAdminActivity,{passive:true});window.addEventListener('scroll',noteAdminActivity,{passive:true});
document.addEventListener('click',e=>{const summary=e.target.closest('.adm-nav-group > summary');if(!summary)return;e.preventDefault();const group=summary.parentNode;group.open=!group.open;saveAdminNavMode(group)});
window.addEventListener('focus',expireAdminNav);document.addEventListener('visibilitychange',()=>{if(!document.hidden)expireAdminNav()});
SITE_CHANGELOG.push({version:'6.3',date:'2026-10-12',author:'Руслан',title:'Сворачиваемые группы левого меню',type:'improvement',priority:'normal',description:'Группы меню раскрываются нажатием на заголовок. Состояние сохраняется в браузере; после пяти минут бездействия меню автоматически сворачивается; работа в админке продлевает выбранное состояние.'});

const adminTourQuery={name:'',type:'',district:'',sort:'manual'};
function adminTourText(text){return String(text||'').normalize('NFKC').toLocaleLowerCase('ru-RU').replaceAll('ё','е').trim()}
function adminTourMatches(){const term=adminTourText(adminTourQuery.name),list=C.tours.map((tour,index)=>({tour,index})).filter(({tour})=>(!term||adminTourText(tour.title).includes(term))&&(!adminTourQuery.type||tour.cat===adminTourQuery.type)&&(!adminTourQuery.district||tour.district===adminTourQuery.district));const label=(t,k)=>k==='type'?(CAT[t.cat]||t.cat||''):k==='district'?(DMAP[t.district]?.name||t.district||''):(t.title||'');if(adminTourQuery.sort!=='manual')list.sort((a,b)=>label(a.tour,adminTourQuery.sort).localeCompare(label(b.tour,adminTourQuery.sort),'ru')||String(a.tour.title).localeCompare(String(b.tour.title),'ru')||a.index-b.index);return list}
function adminTourSearchHTML(){return `<section class="admin-tour-filters"><label class="field admin-tour-name"><span>Название экскурсии</span><input type="search" class="input" data-admin-tour-filter="name" list="adminTourNames" value="${esc(adminTourQuery.name)}" placeholder="Начните вводить название…" autocomplete="off"><datalist id="adminTourNames">${C.tours.map(t=>`<option value="${esc(t.title)}"></option>`).join('')}</datalist></label><label class="field"><span>Тип</span><select class="input" data-admin-tour-filter="type"><option value="">Все типы</option>${Object.entries(CAT).map(([k,v])=>`<option value="${k}" ${adminTourQuery.type===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label class="field"><span>Район</span><select class="input" data-admin-tour-filter="district"><option value="">Все районы</option>${DISTRICTS.map(d=>`<option value="${d.id}" ${adminTourQuery.district===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label><label class="field"><span>Порядок</span><select class="input" data-admin-tour-filter="sort">${[['manual','Как в каталоге'],['name','По названию'],['type','По типу'],['district','По району']].map(([k,v])=>`<option value="${k}" ${adminTourQuery.sort===k?'selected':''}>${v}</option>`).join('')}</select></label><button type="button" class="btn btn-ghost small" data-admin-tour-reset>Сбросить</button><span id="adminTourCount" role="status" aria-live="polite"></span></section>`}
function applyAdminTourSearch(){const root=$('#adminTourList');if(!root)return;const matches=adminTourMatches(),ranks=new Map(matches.map((x,i)=>[x.index,i])),rows=$$('[data-admin-tour-index]',root);rows.forEach(row=>row.hidden=!ranks.has(Number(row.dataset.adminTourIndex)));if(adminTourQuery.sort==='manual')rows.sort((a,b)=>Number(a.dataset.adminTourIndex)-Number(b.dataset.adminTourIndex));else rows.sort((a,b)=>(ranks.get(Number(a.dataset.adminTourIndex))??99999)-(ranks.get(Number(b.dataset.adminTourIndex))??99999));rows.forEach(row=>root.appendChild(row));const count=$('#adminTourCount');if(count)count.textContent='Найдено: '+matches.length+' из '+C.tours.length;const empty=$('#adminTourEmpty');if(empty)empty.hidden=matches.length>0}
const adminToursBeforeSearch=ADM_RENDER.tours;ADM_RENDER.tours=function(parts){adminToursBeforeSearch(parts);if(parts[2])return;const header=$('#admMain .adm-head');header?.insertAdjacentHTML('afterend',adminTourSearchHTML());$('#adminTourList')?.insertAdjacentHTML('afterend','<div class="empty" id="adminTourEmpty" hidden>Экскурсии не найдены. Измените название, тип или район.</div>');applyAdminTourSearch()};
document.addEventListener('input',e=>{const key=e.target.dataset.adminTourFilter;if(!key||!(key in adminTourQuery))return;adminTourQuery[key]=e.target.value;applyAdminTourSearch()});
document.addEventListener('click',e=>{if(!e.target.closest('[data-admin-tour-reset]'))return;Object.assign(adminTourQuery,{name:'',type:'',district:'',sort:'manual'});$$('[data-admin-tour-filter]').forEach(field=>field.value=adminTourQuery[field.dataset.adminTourFilter]);applyAdminTourSearch()});
SITE_CHANGELOG.push({version:'6.4',date:'2026-10-12',author:'Руслан',title:'Поиск и фильтры экскурсий в админке',type:'feature',priority:'normal',description:'Поиск по названию показывает совпадения при вводе. Подсказки названий, фильтры по типу и району, сортировка по названию, типу и району. Скрытые экскурсии остаются доступны редактору.'});

function pendingTourKey(){return 'apsua-new-tour-banner:'+String(serverIdentity?.id||'admin')}
function pendingTourIds(){try{const ids=JSON.parse(localStorage.getItem(pendingTourKey())||'[]');return Array.isArray(ids)?ids:[]}catch{return []}}
function markNewTour(id){try{localStorage.setItem(pendingTourKey(),JSON.stringify([...new Set([...pendingTourIds(),id])]))}catch{}}
function forgetNewTour(id){try{localStorage.setItem(pendingTourKey(),JSON.stringify(pendingTourIds().filter(x=>x!==id)))}catch{}}
function askTourBanner(t){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='tour-banner-dialog';dialog.innerHTML=`<h2>Показывать экскурсию в баннере?</h2><p>${esc(t.title)}</p><p class="sub">Она появится среди популярных маршрутов на главной.${t.hidden?' Сейчас экскурсия скрыта: показ начнётся после включения её видимости.':''}</p><div class="tour-banner-actions"><button type="button" class="btn btn-sea" data-banner-choice="yes">Показывать</button><button type="button" class="btn btn-ghost" data-banner-choice="no">Не показывать</button><button type="button" class="btn btn-ghost small" data-banner-choice="cancel">Отмена</button></div>`;const finish=value=>{dialog.close();dialog.remove();resolve(value)};dialog.addEventListener('click',e=>{const button=e.target.closest('[data-banner-choice]');if(button)finish(button.dataset.bannerChoice==='cancel'?null:button.dataset.bannerChoice==='yes')});dialog.addEventListener('cancel',e=>{e.preventDefault();finish(null)});document.body.append(dialog);dialog.showModal()})}
async function saveTourExplicitly(id){const tour=tourById(id);if(!tour||!serverAdmin)return;const button=$('[data-admin-save-tour]');if(button?.disabled)return;const error=validateTourSettings(C.tours)||validateSiteConfig(C);if(error){admStatus(error,true);toast(error);return}if(button)button.disabled=true;try{if(pendingTourIds().includes(id)){const choice=await askTourBanner(tour);if(choice===null)return;tour.popular=choice;const index=C.tours.findIndex(x=>x.id===id),toggle=$(`[data-k="tours.${index}.popular"]`);if(toggle)toggle.checked=choice}clearTimeout(saveT);const work=async()=>{const content=normalizeMedia(clone(C));delete content.site.adminPass;admStatus('Сохранение на сервере…');const payload=serverEditor?{patch:Object.fromEntries(['tours','services','popularLimit','servicesPartnerVersion','routeStops'].filter(k=>Object.hasOwn(content,k)).map(k=>[k,content[k]])),revision:contentRevision}:{content,revision:contentRevision};const data=await api('/api/content',{method:'PUT',body:JSON.stringify(payload)});contentRevision=data.revision;forgetNewTour(id);admStatus('Сохранено на сервере ✓');toast('Экскурсия сохранена')};const result=serverQueue.then(work);serverQueue=result.catch(()=>{});await result}catch(err){admStatus('Не сохранено: '+err.message,true);toast(err.message)}finally{if(button?.isConnected)button.disabled=false}}
document.addEventListener('click',e=>{const button=e.target.closest('[data-admin-save-tour]');if(button){e.preventDefault();saveTourExplicitly(button.dataset.adminSaveTour)}});
SITE_CHANGELOG.push({version:'6.5',date:'2026-10-12',author:'Руслан',title:'Выбор баннера при сохранении новой экскурсии',type:'feature',priority:'normal',description:'Новая экскурсия создаётся без показа в баннере. Кнопка «Сохранить» спрашивает, добавить ли её в популярные маршруты. Решение сохраняется на сервере; после первого успешного сохранения вопрос не повторяется.'});

let adminBaseline=null,adminDirty=false,adminSaving=false,adminExitBusy=false,adminNavigationPermit=false,adminLastHash=location.hash;
function updateAdminSaveState(){window.apsuaAdminDirty=adminDirty;window.apsuaAdminSaving=adminSaving;$$('[data-admin-save]').forEach(button=>{button.disabled=adminSaving||!adminDirty;button.textContent=adminSaving?'Сохранение…':'Сохранить'});const status=$('#adminDraftStatus');if(status)status.textContent=adminSaving?'Сохранение на сервере…':adminDirty?'Есть несохранённые изменения':'Все изменения сохранены';if(adminDirty)admStatus('Изменения не сохранены')}
function stageAdminContent(){if(!adminBaseline)adminBaseline=clone(C);adminDirty=JSON.stringify(C)!==JSON.stringify(adminBaseline);updateAdminSaveState();return true}
const storeBeforeManualSave=store.set;store.set=function(key,value){if(key==='content'&&serverReady&&serverAdmin)return stageAdminContent();return storeBeforeManualSave(key,value)};
admSave=function(chrome){clearTimeout(saveT);stageAdminContent();if(chrome)renderChrome()};
function resetAdminBaseline(){adminBaseline=clone(C);adminDirty=false;updateAdminSaveState()}
function setupAdminSave(){const root=$('#admMain');if(!root)return;if(!adminDirty&&!adminSaving)resetAdminBaseline();if(!$('#adminSaveBar'))root.insertAdjacentHTML('afterbegin','<div class="admin-save-bar" id="adminSaveBar"><span id="adminDraftStatus" role="status" aria-live="polite"></span><button class="btn btn-sea small" type="button" data-admin-save>Сохранить</button></div>');adminLastHash=location.hash;updateAdminSaveState()}
for(const key of Object.keys(ADM_RENDER)){const original=ADM_RENDER[key];ADM_RENDER[key]=function(...args){const result=original.apply(this,args);setupAdminSave();return result}}
async function saveAdminChanges(){if(adminSaving)return false;const invalid=$('#admMain [data-k]:invalid,#admMain [data-stop-pick]:invalid');if(invalid){invalid.reportValidity?.();toast('Проверьте значение поля');return false}const error=validateTourSettings(C.tours)||validateSiteConfig(C);if(error){admStatus(error,true);toast(error);return false}adminSaving=true;updateAdminSaveState();try{for(const id of pendingTourIds().filter(id=>C.tours.some(t=>t.id===id))){const t=tourById(id),choice=await askTourBanner(t);if(choice===null)return false;t.popular=choice;const index=C.tours.findIndex(x=>x.id===id),toggle=$(`[data-k="tours.${index}.popular"]`);if(toggle)toggle.checked=choice}clearTimeout(saveT);const snapshot=clone(C),content=normalizeMedia(clone(snapshot));delete content.site.adminPass;const work=async()=>{const payload=serverEditor?{patch:Object.fromEntries(['tours','services','popularLimit','servicesPartnerVersion','routeStops'].filter(k=>Object.hasOwn(content,k)).map(k=>[k,content[k]])),revision:contentRevision}:{content,revision:contentRevision};const data=await api('/api/content',{method:'PUT',body:JSON.stringify(payload)});contentRevision=data.revision};const result=serverQueue.then(work);serverQueue=result.catch(()=>{});await result;adminBaseline=snapshot;adminDirty=JSON.stringify(C)!==JSON.stringify(snapshot);snapshot.tours.forEach(t=>forgetNewTour(t.id));admStatus('Сохранено на сервере ✓');toast('Изменения сохранены');window.dispatchEvent(new Event('admin-content-saved'));return true}catch(err){admStatus('Не сохранено: '+err.message,true);toast('Не сохранено: '+err.message);return false}finally{adminSaving=false;updateAdminSaveState()}}
saveTourExplicitly=function(){return saveAdminChanges()};
function discardAdminChanges(){if(!adminBaseline)return;const ids=new Set(adminBaseline.tours.map(t=>t.id));C.tours.filter(t=>!ids.has(t.id)).forEach(t=>forgetNewTour(t.id));C=clone(adminBaseline);clearTimeout(saveT);adminDirty=false;updateAdminSaveState();renderChrome();window.dispatchEvent(new Event('admin-content-discarded'))}
function askUnsavedAdmin(){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='tour-banner-dialog';dialog.innerHTML='<h2>Сохранить изменения?</h2><p class="sub">В админке есть несохранённые изменения.</p><div class="tour-banner-actions"><button type="button" class="btn btn-sea" data-exit-choice="yes">Да, сохранить</button><button type="button" class="btn btn-ghost" data-exit-choice="no">Нет, выйти</button></div>';const finish=value=>{dialog.close();dialog.remove();resolve(value)};dialog.addEventListener('click',e=>{const button=e.target.closest('[data-exit-choice]');if(button)finish(button.dataset.exitChoice)});dialog.addEventListener('cancel',e=>{e.preventDefault();finish(null)});document.body.append(dialog);dialog.showModal()})}
async function exitAdminDraft(proceed){if(adminExitBusy||adminSaving)return;adminExitBusy=true;try{const choice=await askUnsavedAdmin();if(choice==='yes'){if(!await saveAdminChanges())return}else if(choice==='no')discardAdminChanges();else return;adminNavigationPermit=true;proceed();adminNavigationPermit=false}catch(err){toast(err.message)}finally{adminExitBusy=false}}
function guardAdminClick(e){if(adminNavigationPermit||!adminDirty)return;const logout=e.target.closest('[data-logout]'),link=e.target.closest('a[href]');if(!logout&&!link)return;if(link&&(link.target==='_blank'||link.hasAttribute('download')))return;const url=link?new URL(link.href,location.href):null;if(url&&url.href===location.href)return;e.preventDefault();e.stopImmediatePropagation();exitAdminDraft(()=>{if(logout){adminNavigationPermit=true;logout.click()}else if(url.origin===location.origin&&url.pathname===location.pathname&&url.search===location.search){adminLastHash=url.hash;location.hash=url.hash}else location.href=url.href})}
window.addEventListener('hashchange',e=>{const target=location.hash;if(adminNavigationPermit||!adminDirty){adminNavigationPermit=false;adminLastHash=target;return}e.stopImmediatePropagation();history.replaceState(null,'',location.pathname+location.search+adminLastHash);exitAdminDraft(()=>{adminLastHash=target;location.hash=target})},true);
window.addEventListener('beforeunload',e=>{if(adminDirty||adminSaving){e.preventDefault();e.returnValue=''}});
document.addEventListener('click',e=>{if(e.target.closest('[data-admin-save]')){e.preventDefault();saveAdminChanges()}});
SITE_CHANGELOG.push({version:'6.6',date:'2026-10-12',author:'Руслан',title:'Ручное сохранение изменений в админке',type:'improvement',priority:'important',description:'Общая кнопка «Сохранить» вместо автосохранения контента. При переходе предлагается сохранить изменения или выйти без них. Незавершённые правки защищены от автоматического обновления страницы.'});

function bannerPhotos(target){const item=C[target];return Array.isArray(item?.photos)?item.photos.filter(Boolean):item?.photo?[item.photo]:[]}
function bannerImages(target,scene,alt){const photos=bannerPhotos(target);return (photos.length?photos:[null]).map((photo,i)=>`<img src="${esc(src(photo,scene,1600,900))}" alt="${esc(alt)}" class="${i?'':'on'}" ${i?'loading="lazy"':''}>`).join('')}
function bannerPhotoEditor(target,label,note=''){const photos=bannerPhotos(target);return `<div class="field"><span>${esc(label)}</span><p class="sub">Первое фото показывается первым. Несколько снимков плавно сменяются. ${esc(note)} Изменения применятся после нажатия «Сохранить».</p><div class="tphotos banner-photo-editor" data-banner-drop="${target}">${photos.map((photo,i)=>`<figure><img src="${esc(src(photo))}" alt="Фото ${i+1}"><figcaption>${i===0?'<em>Первое фото</em>':''}<button type="button" class="ibtn" data-banner-action="left" data-banner-target="${target}" data-banner-index="${i}" aria-label="Переместить фото влево" ${i===0?'disabled':''}>${ICON.left}</button><button type="button" class="ibtn" data-banner-action="right" data-banner-target="${target}" data-banner-index="${i}" aria-label="Переместить фото вправо" ${i===photos.length-1?'disabled':''}>${ICON.right}</button><button type="button" class="ibtn danger" data-banner-action="delete" data-banner-target="${target}" data-banner-index="${i}" aria-label="Удалить фото">${ICON.trash}</button></figcaption></figure>`).join('')}<label class="tph-add">${ICON.plus}<span>Добавить фото</span><input type="file" accept="image/*" multiple data-banner-photos="${target}" hidden></label></div></div>`}
const photoEditorBeforeBanners=F.photo;F.photo=function(key,label,scene,note=''){if(key==='hero.photo'||key==='transfer.photo')return bannerPhotoEditor(key.split('.')[0],label,note);return photoEditorBeforeBanners(key,label,scene,note)};
function setBannerPhotos(target,photos){if(!['hero','transfer'].includes(target))return;C[target].photos=photos.slice();C[target].photo=photos[0]||'';stageAdminContent()}
async function uploadBannerPhotos(target,files){if(!serverAdmin||serverEditor||!['hero','transfer'].includes(target))return;const added=[];for(const file of files){if(!file.type.startsWith('image/'))continue;const photo=await storePhoto(file,1800);if(photo)added.push(photo)}if(added.length){setBannerPhotos(target,[...bannerPhotos(target),...added]);admRerender();toast('Фото добавлены. Нажмите «Сохранить».')}}
document.addEventListener('change',e=>{const target=e.target.dataset.bannerPhotos;if(target&&e.target.files?.length)uploadBannerPhotos(target,[...e.target.files])});
document.addEventListener('click',e=>{const button=e.target.closest('[data-banner-action]');if(!button||!serverAdmin||serverEditor)return;const target=button.dataset.bannerTarget,photos=bannerPhotos(target),index=Number(button.dataset.bannerIndex);if(button.dataset.bannerAction==='delete')photos.splice(index,1);else{const next=index+(button.dataset.bannerAction==='left'?-1:1);if(next<0||next>=photos.length)return;[photos[index],photos[next]]=[photos[next],photos[index]]}setBannerPhotos(target,photos);admRerender()});
document.addEventListener('dragover',e=>{const box=e.target.closest('[data-banner-drop]');if(box){e.preventDefault();box.classList.add('drag')}});
document.addEventListener('dragleave',e=>e.target.closest('[data-banner-drop]')?.classList.remove('drag'));
document.addEventListener('drop',e=>{const box=e.target.closest('[data-banner-drop]');if(!box)return;e.preventDefault();box.classList.remove('drag');uploadBannerPhotos(box.dataset.bannerDrop,[...(e.dataTransfer.files||[])])});
function advanceBanner(box){const images=$$('img',box);if(images.length<2)return;const active=images.findIndex(img=>img.classList.contains('on')),next=(active+1)%images.length;images.forEach((img,i)=>img.classList.toggle('on',i===next))}
setInterval(()=>{if(document.hidden||window.apsuaVisualActive)return;$$('.banner-gallery').forEach(box=>{const rect=box.getBoundingClientRect();if(rect.bottom>0&&rect.top<innerHeight)advanceBanner(box)})},5000);
SITE_CHANGELOG.push({version:'6.7',date:'2026-10-12',author:'Руслан',title:'Несколько фотографий в баннерах',type:'feature',priority:'normal',description:'Главный баннер и баннер трансфера поддерживают несколько фотографий с плавной сменой. В админке доступны загрузка нескольких файлов, изменение порядка и удаление; публикация после «Сохранить».'});

