/* Shared stop catalog and configurable transfer form. */
const BASE_STOP_POINTS={gagra:[40.27,43.28],pitsunda:[40.34,43.16],ritsa:[40.535,43.478],gudauta:[40.63,43.11],afon:[40.815,43.09],suhum:[41.02,43.003],kamany:[41.1,43.09],gulripsh:[41.102,42.93],dranda:[41.158,42.875],ochamchira:[41.47,42.71],tkuarchal:[41.68,42.84],gal:[41.736,42.625]};
const BASE_STOPS=Object.entries(PIN_NAMES).filter(([id])=>id!=='psou').map(([id,name])=>({id,name,district:PIN_DIST[id],lon:BASE_STOP_POINTS[id]?.[0]??'',lat:BASE_STOP_POINTS[id]?.[1]??''}));
const BASE_MAP_POINTS=clone(GEO.pins);
function stopCatalog(){return Array.isArray(C.routeStops)?C.routeStops:BASE_STOPS}
function syncRouteStops(){for(const id of Object.keys(PIN_NAMES))if(id!=='psou'){delete PIN_NAMES[id];delete PIN_DIST[id];delete GEO.pins[id]}for(const stop of stopCatalog()){PIN_NAMES[stop.id]=stop.name;PIN_DIST[stop.id]=stop.district;PIN_LBL[stop.id]??=[12,-12,'start'];if(stop.lat!==''&&stop.lon!==''&&Number.isFinite(Number(stop.lat))&&Number.isFinite(Number(stop.lon)))GEO.pins[stop.id]=[(Number(stop.lon)-39.75)*416.6666667,(43.75-Number(stop.lat))*570.1333333];else if(BASE_MAP_POINTS[stop.id]&&stop.lat===undefined)GEO.pins[stop.id]=BASE_MAP_POINTS[stop.id]}}
function routeStopsEditor(t,i){const choices=stopCatalog();return `<p class="hint">Километры и время в пути между остановками сайт считает сам по дорогам. Выберите остановки по порядку. Начните вводить название, чтобы найти в списке. Новые остановки добавляются в отдельном справочнике.</p><a class="btn btn-ghost small" href="#/admin/stops">Открыть справочник остановок</a><datalist id="tourStopChoices">${choices.map(s=>`<option value="${esc(s.name)}"></option>`).join('')}</datalist><ol class="route-editor">${t.routePins.map((id,j)=>`<li><label class="field"><span>Остановка ${j+1}</span><input class="input" list="tourStopChoices" data-stop-pick data-tour="${i}" data-stop-index="${j}" value="${esc(PIN_NAMES[id]||'')}" placeholder="Введите название…" autocomplete="off"></label><label class="field route-stay"><span>Сколько стоим</span><input class="input" data-k="tours.${i}.routeStays.${j}" value="${esc((t.routeStays||[])[j]||'')}" maxlength="60" placeholder="Например: 20 мин"></label><div class="route-stop-actions"><button type="button" class="ibtn" data-tour-action="pin-up" data-tour="${i}" data-pin-index="${j}" aria-label="Выше" ${j?'':'disabled'}>↑</button><button type="button" class="ibtn" data-tour-action="pin-down" data-tour="${i}" data-pin-index="${j}" aria-label="Ниже" ${j===t.routePins.length-1?'disabled':''}>↓</button><button type="button" class="btn btn-ghost small danger" data-tour-action="pin-remove" data-tour="${i}" data-pin-index="${j}">Удалить</button></div></li>`).join('')}</ol><button type="button" class="btn btn-ghost small" data-tour-action="pin-add" data-tour="${i}">+ Добавить остановку</button>`}
ADM_TABS.push(['stops','Остановки маршрутов']);
ADM_RENDER.stops=function(){C.routeStops??=clone(BASE_STOPS);const used=id=>C.tours.some(t=>t.pin===id||(t.routePins||[]).includes(id));$('#admMain').innerHTML=`<header class="adm-head"><h1>Остановки маршрутов</h1><p class="sub">Общий список для экскурсий. Координаты необязательны для списка, но нужны для маршрута на карте.</p></header>${card('Справочник остановок',`<input class="input" type="search" data-stop-search placeholder="Найти остановку…" aria-label="Поиск остановок"><div class="stop-catalog">${C.routeStops.map((s,i)=>`<details class="stop-catalog-row" data-stop-row ${s.name?'':'open'}><summary>${esc(s.name||'Новая остановка')}</summary><div class="adm-grid">${F.text(`routeStops.${i}.name`,'Название')}${F.select(`routeStops.${i}.district`,'Район',DISTRICTS.map(d=>[d.id,d.name]))}${F.text(`routeStops.${i}.paid`,'Платный вход · необязательно','Например: вход ~500 ₽')}</div>${F.photo(`routeStops.${i}.photo`,'Фото остановки',['mount',0])}<details class="stop-coordinates"><summary>Координаты для карты · необязательно</summary><div class="adm-grid">${F.num(`routeStops.${i}.lat`,'Широта','any')}${F.num(`routeStops.${i}.lon`,'Долгота','any')}</div></details><button class="btn btn-ghost small danger" type="button" data-stop-delete="${i}" ${used(s.id)?'disabled':''}>Удалить</button>${used(s.id)?'<small class="hint">Используется в экскурсиях: сначала уберите из маршрутов.</small>':''}</details>`).join('')}</div><button class="btn btn-ghost small" type="button" data-stop-add>+ Добавить остановку</button>`)}`;setupCompactAdmin();setupAdminSave()};
document.addEventListener('input',e=>{const el=e.target;if(el.matches('[data-stop-pick]')){const stop=stopCatalog().find(x=>x.name.toLocaleLowerCase('ru')===el.value.trim().toLocaleLowerCase('ru'));el.setCustomValidity(stop?'':'Выберите остановку из списка или добавьте её в справочник');if(stop){C.tours[Number(el.dataset.tour)].routePins[Number(el.dataset.stopIndex)]=stop.id;stageAdminContent()}else{adminDirty=true;updateAdminSaveState()}}if(el.matches('[data-stop-search]'))$$('[data-stop-row]').forEach(row=>{const input=$('input[data-k$=".name"]',row);row.hidden=!(input?.value||row.textContent).toLocaleLowerCase('ru').includes(el.value.toLocaleLowerCase('ru'))})});
document.addEventListener('click',e=>{if(!serverAdmin)return;if(e.target.closest('[data-stop-add]')){C.routeStops??=clone(BASE_STOPS);C.routeStops.push({id:newId('stop-'),name:'',district:'gudauta',lat:'',lon:''});stageAdminContent();ADM_RENDER.stops()}const button=e.target.closest('[data-stop-delete]');if(button){const stop=C.routeStops[Number(button.dataset.stopDelete)];if(C.tours.some(t=>t.pin===stop.id||(t.routePins||[]).includes(stop.id)))return toast('Остановка используется в экскурсии');C.routeStops.splice(Number(button.dataset.stopDelete),1);syncRouteStops();stageAdminContent();ADM_RENDER.stops()}});
const TRANSFER_TERMINALS=[{id:'sochi',name:'Аэропорт Адлер',add:0},{id:'adler',name:'Ж/д вокзал Адлер',add:0},{id:'sukhum',name:'Аэропорт Сухум',add:0},{id:'sukhum-rail',name:'Ж/д вокзал Сухум',add:0},{id:'gagra-rail',name:'Ж/д вокзал Гагра',add:0}];
function ensureTransferConfig(){const T=C.transfer;if(!T)return;T.from??=[];for(const point of TRANSFER_TERMINALS)if(!T.from.some(x=>x.id===point.id))T.from.push(clone(point));const adler=T.from.find(x=>x.id==='sochi');if(adler?.name==='Аэропорт Сочи')adler.name='Аэропорт Адлер';T.groupPolicy??={enabled:true,start:'05-01',end:'10-31'};T.hotels??=[]}
function transferGroupAvailable(date){const p=C.transfer.groupPolicy||{enabled:true,start:'05-01',end:'10-31'},md=String(date).slice(5);return !!p.enabled&&/^\d{2}-\d{2}$/.test(md)&&(p.start<=p.end?md>=p.start&&md<=p.end:md>=p.start||md<=p.end)}
function transferHotels(){return (C.transfer.hotels||[]).filter(h=>h.city===tr.to&&h.name&&h.address)}
function departureDeadlineOK(date,time,now=Date.now()){const at=Date.parse(date+'T'+time+':00+03:00');return Number.isFinite(at)&&at-now>=12*3600000}
function validateSiteConfig(content){const stops=content.routeStops||[],ids=new Set(),names=new Set();for(const s of stops){if(!s.id||ids.has(s.id)||!s.name?.trim()||names.has(s.name.trim().toLocaleLowerCase('ru')))return 'У каждой остановки должно быть уникальное название';ids.add(s.id);names.add(s.name.trim().toLocaleLowerCase('ru'));if((s.lat==='')!==(s.lon==='')||s.lat!==''&&s.lat!==undefined&&(!Number.isFinite(Number(s.lat))||!Number.isFinite(Number(s.lon))||Number(s.lat)<42||Number(s.lat)>44||Number(s.lon)<39||Number(s.lon)>43))return 'Проверьте координаты остановки: укажите широту и долготу или оставьте обе пустыми'}const policy=content.transfer?.groupPolicy;if(policy&&(!validMonthDay(policy.start)||!validMonthDay(policy.end)))return 'Укажите начало и конец сезона группового трансфера';for(const h of content.transfer?.hotels||[])if(!h.name?.trim()||!h.address?.trim()||!content.transfer.to.some(x=>x.id===h.city))return 'Укажите город, название и адрес каждого отеля';return ''}
function validMonthDay(md){if(!/^\d\d-\d\d$/.test(md||''))return false;const date=new Date('2024-'+md+'T12:00:00Z');return Number.isFinite(date.getTime())&&date.toISOString().slice(5,10)===md}
const transferAdminBeforeExtras=ADM_RENDER.transfer;ADM_RENDER.transfer=function(){ensureTransferConfig();transferAdminBeforeExtras();$('#admMain').insertAdjacentHTML('beforeend',card('Сезон группового трансфера',`<p class="hint">Вне выбранного периода доступны только индивидуальные трансферы. Даты повторяются ежегодно, последний день включён. Начальный период: 1 мая–31 октября.</p>${F.bool('transfer.groupPolicy.enabled','Групповой трансфер разрешён в сезон')}<div class="adm-grid"><label class="field"><span>Начало сезона · день и месяц</span><input class="input" type="date" data-k="transfer.groupPolicy.start" data-t="season-date" value="${new Date().getFullYear()}-${esc(C.transfer.groupPolicy.start)}" required></label><label class="field"><span>Конец сезона · день и месяц</span><input class="input" type="date" data-k="transfer.groupPolicy.end" data-t="season-date" value="${new Date().getFullYear()+(C.transfer.groupPolicy.end<C.transfer.groupPolicy.start?1:0)}-${esc(C.transfer.groupPolicy.end)}" required></label></div>`)+card('Отели и точные адреса',`<p class="hint">Список отелей для каждого населённого пункта. На сайте выбор отеля подставит адрес, который турист сможет уточнить.</p><div class="hotel-catalog">${C.transfer.hotels.map((h,i)=>`<details class="hotel-catalog-row" ${h.name?'':'open'}><summary>${esc(h.name||'Новый отель')} · ${esc(C.transfer.to.find(c=>c.id===h.city)?.name||'')}</summary><div class="adm-grid">${F.select(`transfer.hotels.${i}.city`,'Город',C.transfer.to.map(x=>[x.id,x.name]))}${F.text(`transfer.hotels.${i}.name`,'Название отеля')}</div>${F.text(`transfer.hotels.${i}.address`,'Точный адрес')}<button class="btn btn-ghost small danger" type="button" data-hotel-delete="${i}">Удалить отель</button></details>`).join('')}</div><button class="btn btn-ghost small" type="button" data-hotel-add>+ Добавить отель</button>`));setupCompactAdmin();setupAdminSave()};
document.addEventListener('click',e=>{if(!serverAdmin||serverEditor)return;if(e.target.closest('[data-hotel-add]')){C.transfer.hotels.push({id:newId('hotel-'),city:C.transfer.to[0]?.id||'',name:'',address:''});stageAdminContent();ADM_RENDER.transfer()}const button=e.target.closest('[data-hotel-delete]');if(button){C.transfer.hotels.splice(Number(button.dataset.hotelDelete),1);stageAdminContent();ADM_RENDER.transfer()}});
