const orderPrintBeforeFleet=orderFingerprint;orderFingerprint=function(order){return orderPrintBeforeFleet(order)+':'+String(hash(JSON.stringify(order.assignedVehicle||null)))};
function ensureFleetDraft(){if(!C.fleet)C.fleet={vehicles:Fleet.presentationVehicles(),company:Fleet.companyDefaults()};if(!C.fleet.company)C.fleet.company=Fleet.companyDefaults();return C.fleet}
function fleetEditorVehicle(v,index){const k=key=>`fleet.vehicles.${index}.${key}`;return `<details class="fleet-admin-vehicle" ${v._new?'open':''}><summary><span>${esc(v.name)}</span><small>${esc(Fleet.types[v.type])}${v.hidden?' · скрыт':''}${v.example?' · пример':''}</small></summary><div class="fleet-admin-fields"><div class="adm-grid3">${F.text(k('name'),'Название / модель')}${F.select(k('type'),'Тип',Object.entries(Fleet.types))}${F.num(k('capacity'),'Пассажиров · пусто, если уточняется')}</div><div class="adm-grid">${F.num(k('luggage'),'Мест багажа · пусто, если уточняется')}${F.lines(k('features'),'Комфорт и особенности',2,'Например: кондиционер, USB')}</div><div class="adm-flags">${F.bool(k('transfer'),'Для трансферов')}${F.bool(k('excursion'),'Для экскурсий')}${F.bool(k('individual'),'Индивидуальные поездки')}${F.bool(k('group'),'Групповые поездки')}${F.bool(k('hidden'),'Скрыть')}${F.bool(k('example'),'Пример · без выбора в заявке')}</div><details><summary>Привязка к классам трансфера</summary><p class="hint">Если не отмечено — подходят совместимые классы по типу машины и числу пассажиров.</p><div class="adm-flags">${C.transfer.classes.map(c=>`<label class="check"><input type="checkbox" data-fleet-class="${esc(c.id)}" data-vehicle-index="${index}" ${(v.transferClassIds||[]).includes(c.id)?'checked':''}>${esc(c.name)}</label>`).join('')}</div></details><div class="fleet-admin-photos">${(v.photos||[]).map((photo,i)=>`<figure><img src="${esc(Fleet.safePhoto(photo))}" alt="Фото ${i+1}"><figcaption><button type="button" class="ibtn" data-fleet-photo-up="${i}" data-vehicle-index="${index}" aria-label="Сделать фото раньше" ${i?'':'disabled'}>${ICON.left}</button><button type="button" class="ibtn" data-fleet-photo-delete="${i}" data-vehicle-index="${index}" aria-label="Удалить фото">${ICON.trash}</button></figcaption></figure>`).join('')}<label class="btn btn-ghost small">${ICON.img}Добавить фото<input type="file" accept="image/jpeg,image/png,image/webp" multiple data-fleet-upload="${index}" hidden></label></div><small>До 12 фото. Первое — обложка. Загруженные фото и правки публикуются после «Сохранить».</small><div class="comfort-actions"><button class="btn btn-ghost small" type="button" data-fleet-up="${index}" ${index?'':'disabled'}>Выше</button><button class="btn btn-ghost small danger" type="button" data-fleet-delete="${index}">Удалить карточку</button></div></div></details>`}
ADM_TABS.splice(ADM_TABS.findIndex(x=>x[0]==='transfer')+1,0,['fleet','Автопарк']);adminGroups.find(x=>x[0]==='Контент')[1].push('fleet');
ADM_RENDER.fleet=function(){const f=ensureFleetDraft();$('#admMain').innerHTML=`<header class="adm-head"><h1>Автопарк</h1><div class="head-btns"><a class="btn btn-ghost small" href="#/fleet" target="_blank">Открыть каталог</a><button type="button" class="btn btn-sea small" data-fleet-add>Добавить автомобиль</button></div></header>${card('Модели и фотографии',`<p class="hint">Один справочник для всего сайта. Модели и фото из презентации уже добавлены. Примеры не выбираются в заявке: замените название и данные, добавьте фото и выключите «Пример». Номера и назначения диспетчера здесь не задаются.</p><label class="field">Найти карточку<input class="input" data-fleet-admin-search type="search" placeholder="Название или модель"></label><div id="fleetAdminVehicles">${f.vehicles.map(fleetEditorVehicle).join('')}</div>`)}${card('О компании и партнёрам',`${F.text('fleet.company.title','Заголовок')}${F.area('fleet.company.intro','Коротко о компании',2)}${F.area('fleet.company.body','Подробнее',5)}${F.area('fleet.company.partners','Условия сотрудничества',4)}<p class="hint">Информация подготовлена по презентации компании. Тексты редактируются здесь; изменения публикуются кнопкой «Сохранить». Для звонка используются действующие контакты сайта.</p>`)}`;setupCompactAdmin();setupAdminSave()};
const tourEditorBeforeFleet=ADM_RENDER.tour;ADM_RENDER.tour=function(id){tourEditorBeforeFleet(id);const index=C.tours.findIndex(t=>t.id===id);if(index<0)return;const selected=C.tours[index].vehicleIds||[];$('#admMain').insertAdjacentHTML('beforeend',card('Транспорт на маршруте',`<p class="hint">Если ничего не отмечено — показываются все подходящие экскурсионные автомобили. Для индивидуальной поездки турист может оставить пожелание.</p><div class="adm-flags">${Fleet.vehicles(C,true).filter(v=>v.excursion).map(v=>`<label class="check"><input type="checkbox" data-tour-vehicle="${esc(v.id)}" data-tour-index="${index}" ${selected.includes(v.id)?'checked':''}>${esc(v.name)}${v.hidden?' · скрыт':''}</label>`).join('')||'<a href="#/admin/fleet">Сначала добавьте транспорт</a>'}</div>`));setupCompactAdmin();setupAdminSave()};
const siteValidationBeforeFleet=validateSiteConfig;validateSiteConfig=function(content){return siteValidationBeforeFleet(content)||Fleet.validate(content)};
const chromeBeforeFleet=renderChrome;renderChrome=function(...args){const r=chromeBeforeFleet.apply(this,args),links=$('.footer-links');if(links&&!links.querySelector('[data-fleet-footer]'))links.insertAdjacentHTML('beforeend','<a href="#/fleet" data-fleet-footer>Автопарк</a><a href="#/about" data-fleet-footer>О компании и контакты</a>');return r};
let fleetDialog=null;function openFleetVehicle(id){const v=Fleet.vehicles(C).find(v=>v.id===id);if(!v)return;fleetDialog?.remove();const box=document.createElement('dialog');box.className='tour-banner-dialog fleet-dialog';const photos=(v.photos||[]).map(Fleet.safePhoto).filter(Boolean);box.innerHTML=`<header><h2>${esc(v.name)}</h2><button type="button" class="ibtn" data-fleet-close aria-label="Закрыть">✕</button></header><div class="fleet-photo-strip">${photos.length?photos.map(photo=>`<img src="${esc(photo)}" alt="${esc(v.name)}">`).join(''):fleetPhoto(v)}</div><p>${fleetMeta(v)}</p><p class="hint">${v.example?'Пример типа транспорта. Реальные фото и характеристики будут добавлены.':'Фото модели из презентации компании или каталога. Комплектацию и доступность конкретного автомобиля на дату подтверждает диспетчер.'}</p>`;box.addEventListener('click',e=>{if(e.target===box||e.target.closest('[data-fleet-close]'))box.close()});box.addEventListener('close',()=>{box.remove();if(fleetDialog===box)fleetDialog=null});document.body.append(box);fleetDialog=box;box.showModal()}
document.addEventListener('input',e=>{if(e.target.dataset.fleetFilter){fleetFilters[e.target.dataset.fleetFilter]=e.target.value;renderFleetResults()}if(e.target.matches('[data-fleet-admin-search]')){const q=e.target.value.toLocaleLowerCase('ru');$$('#fleetAdminVehicles>details').forEach(n=>n.hidden=!n.querySelector('summary').textContent.toLocaleLowerCase('ru').includes(q))}});
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.fleetFilter){fleetFilters[t.dataset.fleetFilter]=t.value;renderFleetResults()}if(t.dataset.preferredVehicle){const state=t.dataset.preferredVehicle==='bookings'?bk:tr;state.preferredVehicleId=t.value;saveRequestDraft(t.dataset.preferredVehicle)}if(t.dataset.tourVehicle){const tour=C.tours[Number(t.dataset.tourIndex)];if(!C.fleet)ensureFleetDraft();const ids=new Set(tour.vehicleIds||[]);if(t.checked)ids.add(t.dataset.tourVehicle);else ids.delete(t.dataset.tourVehicle);tour.vehicleIds=[...ids];admSave()}if(t.dataset.fleetClass){const v=ensureFleetDraft().vehicles[Number(t.dataset.vehicleIndex)],ids=new Set(v.transferClassIds||[]);if(t.checked)ids.add(t.dataset.fleetClass);else ids.delete(t.dataset.fleetClass);v.transferClassIds=[...ids];admSave()}if(t.dataset.fleetUpload!==undefined){const v=ensureFleetDraft().vehicles[Number(t.dataset.fleetUpload)];if(!v)return;const files=[...t.files].slice(0,12-(v.photos||[]).length);if(!files.length)return;const old=t.disabled;t.disabled=true;try{for(const file of files){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024){toast('Фото: JPG, PNG или WebP до 15 МБ');continue}const stored=await storePhoto(file,1600);const url=stored?.startsWith('img:')?mediaMapping[stored.slice(4)]||IMG[stored.slice(4)]:stored;if(!C.fleet?.vehicles.includes(v))return;if(url&&Fleet.safePhoto(url))(v.photos||(v.photos=[])).push(url)}admSave();ADM_RENDER.fleet()}catch(err){toast('Не удалось загрузить фото: '+err.message)}finally{t.disabled=old}}});
document.addEventListener('click',e=>{const view=e.target.closest('[data-fleet-view]');if(view){openFleetVehicle(view.dataset.fleetView);return}if(e.target.closest('[data-fleet-add]')){ensureFleetDraft().vehicles.push({id:'vehicle-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6),name:'Новый автомобиль',type:'minivan',capacity:null,luggage:null,features:[],photos:[],transfer:true,excursion:true,individual:true,group:true,hidden:false,example:false,transferClassIds:[],_new:true});admSave();ADM_RENDER.fleet();return}const action=e.target.closest('[data-fleet-delete],[data-fleet-up],[data-fleet-photo-up],[data-fleet-photo-delete]');if(!action)return;const f=ensureFleetDraft(),d=action.dataset;if(d.fleetDelete!==undefined){const v=f.vehicles[Number(d.fleetDelete)];if(C.tours.some(t=>(t.vehicleIds||[]).includes(v.id)))return toast('Сначала уберите автомобиль из экскурсий или скройте карточку.');f.vehicles.splice(Number(d.fleetDelete),1)}if(d.fleetUp!==undefined){const i=Number(d.fleetUp);if(i>0)[f.vehicles[i-1],f.vehicles[i]]=[f.vehicles[i],f.vehicles[i-1]]}if(d.fleetPhotoUp!==undefined){const i=Number(d.fleetPhotoUp),v=f.vehicles[Number(d.vehicleIndex)];if(i>0)[v.photos[i-1],v.photos[i]]=[v.photos[i],v.photos[i-1]]}if(d.fleetPhotoDelete!==undefined)f.vehicles[Number(d.vehicleIndex)].photos.splice(Number(d.fleetPhotoDelete),1);admSave();ADM_RENDER.fleet()});
SITE_CHANGELOG.push({version:'12.8',date:'2026-10-16',author:'Руслан',title:'Единый автопарк и информация о компании',type:'feature',priority:'normal',description:'Каталог транспорта с поиском и фильтрами, фото, местами, багажом и особенностями. В админке — карточки, несколько фото, порядок и привязки к поездкам. Отдельная страница для информации о компании и партнёров. Существующий дизайн сохранён.'});
SITE_CHANGELOG.push({version:'12.9',date:'2026-10-16',author:'Руслан',title:'Транспорт в поездках и пожелание к автомобилю',type:'feature',priority:'normal',description:'Компактные блоки подходящего транспорта в экскурсиях и трансфере. Для индивидуальной поездки можно передать необязательное пожелание из реального каталога; групповую машину назначает диспетчер. Совместимость проверяет сервер.'});
