SITE_CHANGELOG.push({"version":"13.7","date":"2026-10-24","author":"Руслан","title":"Истории публикует только модератор","type":"improvement","priority":"normal","description":"Автоматическая публикация через 48 часов удалена: история ждёт решения модератора. Если автор меняет уже опубликованную историю, она снова отправляется на модерацию."});
SITE_CHANGELOG.push({"version":"13.8","date":"2026-10-24","author":"Руслан","title":"Оформление в стиле Apple","type":"feature","priority":"important","description":"Нейтральная палитра Apple и один синий акцент, системный шрифт, кнопки и чипы-капсулы, карточки без рамок с мягкой тенью, единые скругления фото и полей, полупрозрачные шапка и нижние панели. Отклик на нажатие у всех кнопок, плавная смена темы, поддержка режимов «меньше прозрачности» и «больше контраста». Счётчик избранного скрыт, пока он пуст."});
SITE_CHANGELOG.push({"version":"13.9","date":"2026-10-24","author":"Руслан","title":"Вход через Telegram","type":"feature","priority":"important","description":"Туристы входят в личный кабинет через Telegram в одно касание и могут отправлять заявки. Сервер проверяет подпись Telegram и открывает личную сессию на 30 дней. Вход владельца через ChatGPT сохранён."});
SITE_CHANGELOG.push({"version":"14.0","date":"2026-10-24","author":"Руслан","title":"Заявка по этапам: диспетчер, оплата, водитель","type":"feature","priority":"important","description":"Карточка заявки показывает ответ диспетчера: «У диспетчера», причину отказа, окно оплаты по QR СБП со сроком, время подачи, экскурсовода и водителя с фото, машину с госномером и кнопками «Позвонить» и WhatsApp. Номер заявки из программы диспетчера заменяет номер сайта. Турист может отменить заявку до оплаты."});
SITE_CHANGELOG.push({"version":"14.1","date":"2026-10-24","author":"Руслан","title":"Уведомление о каждом изменении заявки","type":"feature","priority":"important","description":"При подтверждении, выставлении счёта, оплате, отказе и назначении экскурсовода или водителя турист получает push на все свои устройства; нажатие открывает его заявки."});
SITE_CHANGELOG.push({"version":"14.2","date":"2026-10-24","author":"Руслан","title":"Подготовлен обмен с программой диспетчера","type":"feature","priority":"normal","description":"Новые и отменённые заявки отправляются в программу диспетчера, а её решения принимаются по подписанному вебхуку. Обмен включается секретами сервера; формат описан в docs/dispatch-api.md."});
SITE_CHANGELOG.push({"version":"14.3","date":"2026-10-24","author":"Руслан","title":"Формы заявок без автопарка","type":"improvement","priority":"normal","description":"Со страницы экскурсии и из форм убраны блок автопарка и выбор машины — транспорт назначает диспетчер. В форме экскурсии поле «Где вы живёте» с подсказками отелей; тексты говорят про диспетчера, бесплатную отмену до оплаты и оплату по QR."});
