SITE_CHANGELOG.push({"version": "14.5", "date": "2026-10-24", "author": "Руслан", "title": "Новая главная в стиле Apple", "type": "feature", "priority": "important", "description": "Один баннер с кнопками «Экскурсии» и «Трансфер», ленты «Куда поехать», «Чаще всего бронируют», отзывы с оценкой Яндекс Карт, истории из дневника, четыре шага до поездки и цветные карточки «Вам пригодится». Шапка: логотип, разделы по центру и тихие значки; внизу на телефоне — Главная, Экскурсии, Трансфер, Заявки, Профиль."});
